/* Compact desktop dock, with a persistent expand control when minimized. */
(()=>{const dock=document.getElementById('spatialDock');dock.addEventListener('click',event=>{const selected=event.target.closest?.('button');if(!selected||!dock.contains(selected))return;dock.querySelectorAll('button').forEach(button=>{button.dataset.userSelected=button===selected?'true':'false'})});const toggle=document.createElement('button');toggle.id='dockToggle';toggle.type='button';toggle.setAttribute('aria-controls','spatialDock');document.getElementById('shell').append(toggle);let minimized=false;function apply(){dock.classList.toggle('is-minimized',minimized);toggle.classList.toggle('is-minimized',minimized);toggle.textContent=minimized?'◈ Open tools':'−';toggle.setAttribute('aria-label',minimized?'Expand navigation':'Minimize navigation');toggle.setAttribute('aria-expanded',String(!minimized));toggle.title=minimized?'Expand navigation':'Minimize navigation';try{localStorage.setItem('globiquest.dock-minimized',String(minimized))}catch{}}toggle.onclick=()=>{minimized=!minimized;apply()};apply()})();
